class InventoryFile:

    @classmethod
    def loads(cls, content: bytes, *, uri: str) -> _Inventory:
        """Load an inventory from a byte string.

        Inventory version 1 is a plain-text format.  Version 2 has four
        uncompressed header lines followed by a zlib-compressed body.
        """
        if not isinstance(content, bytes):
            raise TypeError('inventory content must be bytes')

        first_line, separator, remainder = content.partition(b'\n')
        if not separator:
            raise ValueError('invalid inventory header')

        try:
            header = first_line.decode('utf-8').rstrip('\r')
        except UnicodeDecodeError as exc:
            raise ValueError('invalid inventory header') from exc

        if header == '# Sphinx inventory version 1':
            try:
                lines = remainder.decode('utf-8').splitlines()
            except UnicodeDecodeError as exc:
                raise ValueError('invalid inventory encoding') from exc
            return cls._loads_v1(lines, uri=uri)
        if header == '# Sphinx inventory version 2':
            return cls._loads_v2(remainder, uri=uri)

        msg = f'unknown or unsupported inventory version: {header!r}'
        raise ValueError(msg)
    @classmethod
    def load(cls, stream: _SupportsRead, uri: str, joinfunc: _JoinFunc) -> Inventory:
        return cls.loads(stream.read(), uri=uri).data

    @classmethod
    def _loads_v1(cls, lines: Sequence[str], *, uri: str) -> _Inventory:
        if len(lines) < 2:
            msg = 'invalid inventory header: missing project name or version'
            raise ValueError(msg)
        inv = _Inventory({})
        projname = lines[0].rstrip()[11:]  # Project name
        version = lines[1].rstrip()[11:]  # Project version
        for line in lines[2:]:
            name, item_type, location = line.rstrip().split(None, maxsplit=2)
            location = posixpath.join(uri, location)
            # version 1 did not add anchors to the location
